      listeningQuestion: "What should the summary include?",
      listeningOptions: <String>["Only the most exciting claim", "A guarantee that the routine works", "The finding and limits affecting interpretation"],
      listeningAnswer: 2,
      readingQuestion: "Why was a causal conclusion uncertain?",
      readingOptions: <String>["Participants might already differ in motivation", "The researcher refused all questions", "No exam results existed"],
      readingAnswer: 0,
      writingCue: "The ____ sounded convincing, but a student journalist noticed that the participant pool came from one voluntary club.",
      writingAnswer: "research summary",
    ),
    EnglishAdvancedLesson(
